ROUTES = [
    ("/api/v2/payments/", "payment-svc:8080"),
    ("/api/v2/orders/", "orders-svc:8080"),
]

def route(path: str, tenant: str, pct: dict) -> str:
    # Dumb by design: prefix match + explicit canary map.
    # Trade-off: config churn here vs. redeploys everywhere else.
    for prefix, target in ROUTES:
        if path.startswith(prefix):
            # canary by tenant before global flip
            if tenant in pct.get(prefix, {}).get("allowlist", []):
                return target
            if pct.get(prefix, {}).get("percent", 0) >= 100:
                return target
            break
    return "monolith:8080"  # default stays on legacy

// Anti-corruption layer: legacy quirks die here, never in the new domain.
class PaymentAdapter {
    Payment toDomain(LegacyPaymentRow row) {
        // WHY translate: legacy uses -1 for unknown, nullable currency,
        // and stringly-typed status. New service uses explicit enums.
        if (row == null) throw new NotFoundException();
        String currency = row.currency == null ? "USD" : row.currency;
        PaymentStatus s = switch (row.statusStr) {
            case "OK", "SETTLED" -> PaymentStatus.CAPTURED;
            case "PEND", "WAIT" -> PaymentStatus.PENDING;
            default -> PaymentStatus.FAILED;
        };
        return new Payment(row.id, row.amountCents, currency, s);
    }
}
